export const PdfCropInput = Schema.Struct({
  privatePath: Schema.String,
  outputPath: Schema.String,
  page: Page,
  box: PixelBox,
})
const CropOutput = Schema.Struct({ width: Schema.Int, height: Schema.Int, byteCount: Schema.Int, hash: ArtifactHash })

const crop = Effect.fn("PdfRenderer.crop")(function* (input: typeof PdfCropInput.Type) {
  const request = yield* Schema.decodeUnknownEffect(PdfCropInput)(input, { onExcessProperty: "error" }).pipe(Effect.mapError(() => failure("invalid-input")))
  const { box, page } = request
  if (![request.privatePath, request.outputPath].every((value) => path.isAbsolute(value) && !value.includes("\0")) || !path.isAbsolute(options.pythonBin) || ![box.x, box.y, box.width, box.height].every(Number.isSafeInteger) || box.x + box.width > page.width || box.y + box.height > page.height) return yield* failure("invalid-input")
  return yield* Effect.scoped(Effect.gen(function* () {
    const process = yield* spawner.spawn(ChildProcess.make(options.pythonBin, ["-I", "-c", CROP_SCRIPT, JSON.stringify(request)], { stdin: "ignore", env: {}, extendEnv: false, forceKillAfter: "100 millis" })).pipe(Effect.mapError(() => failure("processing-unavailable")))
    const result = yield* Effect.all({ stdout: collect(process.stdout), stderr: collect(process.stderr), exitCode: process.exitCode }, { concurrency: "unbounded" }).pipe(Effect.mapError(() => failure("processing-unavailable")))
    if (result.exitCode !== 0) return yield* failure(result.exitCode === 1 ? "invalid-input" : "processing-unavailable")
    const output = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(CropOutput))(result.stdout, { onExcessProperty: "error" }).pipe(Effect.mapError(() => failure("invalid-input")))
    if (output.width !== box.width || output.height !== box.height || output.byteCount <= 0 || output.byteCount > PdfRenderLimits.maxImageBytes) return yield* failure("invalid-input")
    return output
  })).pipe(Effect.timeoutOrElse({ duration: "20 seconds", orElse: () => Effect.fail(failure("limit-exceeded")) }))
})
return PdfRenderer.of({ render, crop })

